// Generated by the Haspataal MCP server (generate_typescript) from the backend contract.
// api(): the helper from get_guide("envelope-and-errors"). Types come from the declared request and response models.
import { api } from "./api";

/** Data for the ID card designer; the frontend renders and prints it on the card printer. */
export interface IdCardOut {
  document_type: "autopsy_order" | "bed_labels" | "blood_component_label" | "blood_donation_labels" | "clinical_note" | "complaint_letter" | "complaints_notice" | "consent_form" | "cost_estimate" | "cssd_labels" | "death_certificate" | "discharge_summary" | "dispensing_label" | "dose_label" | "id_card" | "imaging_report" | "lab_label" | "lab_report" | "mlc_intimation" | "opd_slip" | "pharmacy_receipt" | "prescription" | "referral_slip" | "send_out_manifest" | "surgical_record" | "triage_algorithm" | "wristband";
  printer_role: "receipt" | "label" | "document" | "card";
  card_size_mm: number[];
  fields: IdCardFieldsOut;
  barcode_svg: string;
  qr_svg: string;
  /** The printed staff badge for barcode stations, if one is issued */
  badge: PrintedBadgeOut | null;
}

export interface IdCardFieldsOut {
  hospital_name: string;
  full_name: string;
  designation: string;
  department: string | null;
  emp_number: string;
  blood_group: "A+" | "A-" | "B+" | "B-" | "AB+" | "AB-" | "O+" | "O-" | "Unknown" | null;
  joined_on: string | null;
  license: string | null;
  photo_document_id: number | null;
}

export interface PrintedBadgeOut {
  badge_code: string;
  qr_svg: string;
  barcode_svg: string;
}

/** This terminal's location, printers and cash node. The location and printer fields are present only when `registered` is true; `hint` only when it is false. */
export interface TerminalIdentityOut {
  registered: boolean;
  client_ip: string | null;
  mac: string | null;
  hint?: string | null;
  location_label?: string | null;
  cash_node?: "MainReception" | "PharmacyCounter" | "LabReception" | "IPDBilling" | "EmergencyCounter" | "CashierDesk" | null;
  ip?: string | null;
  receipt_printer?: string | null;
  receipt_printer_address?: string | null;
  receipt_paper_mm?: number | null;
  label_printer?: string | null;
  label_printer_address?: string | null;
  document_printer?: string | null;
  document_printer_address?: string | null;
  card_printer?: string | null;
  card_printer_address?: string | null;
}

/** ID card designer payload (barcode + QR of the EMP number) — GET /api/v1/hr/employees/{employee_id}/id-card (who may call: holders of hr.idcard.print). */
export function idCard(employee_id: number): Promise<IdCardOut> {
  return api<IdCardOut>("GET", `/hr/employees/${employee_id}/id-card`, undefined);
}

/** Identify this terminal (location + mapped printers) — works before login — GET /api/v1/terminals/whoami (who may call: public: no login (works before login)). */
export function whoami(): Promise<TerminalIdentityOut> {
  return api<TerminalIdentityOut>("GET", `/terminals/whoami`, undefined);
}
